    11→export type CreateFavoriteRequest = {
    12→  propertyId: string;
    13→  notes?: string;
    14→  priority?: "high" | "medium" | "low";
    15→};
    16→
    17→export type UpdateFavoriteRequest = {
    18→  id: string;
    19→  notes?: string;
    20→  status?: "saved" | "visited" | "contacted" | "rejected";
    21→  priority?: "high" | "medium" | "low";
