    24→export async function getFavoritesAction() {
    25→  const session = await auth.api.getSession({
    26→    headers: await headers(),
    27→  });
    28→
    29→  if (!session?.user.id) {
    30→    redirect("/auth/signin");
    31→  }
    32→
    33→  const favorites = await prisma.favorite.findMany({
    34→    where: {
    35→      userId: session.user.id,
    36→    },
    37→    include: {
    38→      property: true,
    39→    },
    40→    orderBy: {
    41→      createdAt: "desc",
    42→    },
    43→  });
    44→
    45→  return favorites;
    46→}
    47→
    48→export async function createFavoriteAction(request: CreateFavoriteRequest) {
    49→  logger.debug(
    50→    "🔍 [Favorites] Creating favorite for property:",
    51→    request.propertyId,
    52→  );
    53→
    54→  const session = await auth.api.getSession({
    55→    headers: await headers(),
    56→  });
    57→
    58→  if (!session?.user.id) {
    59→    redirect("/auth/signin");
    60→  }
    61→
    62→  logger.debug("🔍 [Favorites] User ID:", session.user.id);
    63→
    64→  // Check if property exists, if not create it
    65→  let property = await prisma.property.findUnique({
    66→    where: { externalId: request.propertyId },
    67→  });
    68→
    69→  logger.debug("🔍 [Favorites] Property exists:", property ? "YES" : "NO");
    70→
    71→  if (!property) {
    72→    try {
    73→      logger.debug("🔍 [Favorites] Creating new property in database...");
    74→      logger.debug(
    75→        "🔍 [Favorites] Fetching property data from MoteurImmo API...",
    76→      );
    77→
    78→      // Récupérer les vraies données du bien via MoteurImmo API
    79→      const moteurImmoProperty = await moteurImmoClient.getListingById(
    80→        request.propertyId,
    81→      );
    82→      logger.debug(
    83→        "✅ [Favorites] Property data fetched from MoteurImmo:",
    84→        moteurImmoProperty.title,
    85→      );
    86→
    87→      property = await prisma.property.create({
    88→        data: {
    89→          externalId: request.propertyId,
    90→          title: moteurImmoProperty.title,
    91→          description: moteurImmoProperty.description,
    92→          type: moteurImmoProperty.type,
    93→          category: moteurImmoProperty.category,
    94→          price: moteurImmoProperty.price,
    95→          surface: moteurImmoProperty.surface,
    96→          rooms: moteurImmoProperty.rooms,
    97→          bedrooms: moteurImmoProperty.bedrooms,
    98→          floor: moteurImmoProperty.floor,
    99→          totalFloors: moteurImmoProperty.totalFloors,
   100→          address: moteurImmoProperty.address ?? "",
   101→          city: moteurImmoProperty.city,
   102→          postalCode: moteurImmoProperty.postalCode ?? "",
   103→          department: "", // Required by Prisma schema
   104→          region: "", // Required by Prisma schema
   105→          energyClass: moteurImmoProperty.energyClass,
   106→          hasGarden: moteurImmoProperty.hasGarden,
   107→          hasParking: moteurImmoProperty.hasParking,
   108→          hasLift: moteurImmoProperty.hasLift,
   109→          hasTerrace: moteurImmoProperty.hasTerrace,
   110→          hasBalcony: moteurImmoProperty.hasBalcony,
   111→          sourceUrl: moteurImmoProperty.url,
   112→          sourceId: moteurImmoProperty.origin,
   113→          publishedAt: new Date(moteurImmoProperty.publishedAt),
   114→        },
   115→      });
   116→      logger.debug("✅ [Favorites] Property created with ID:", property.id);
   117→    } catch (error) {
   118→      logger.debug("❌ [Favorites] Error creating property:", error);
   119→      // Si l'API MoteurImmo échoue, créer un placeholder comme avant
   120→      logger.debug(
   121→        "🔍 [Favorites] Fallback: Creating placeholder property...",
   122→      );
   123→      property = await prisma.property.create({
   124→        data: {
   125→          externalId: request.propertyId,
   126→          title: "Bien immobilier - Données en cours de chargement",
   127→          type: "sale",
   128→          category: "flat",
   129→          price: 0,
   130→          address: "Adresse en cours de chargement...",
   131→          city: "Ville inconnue",
   132→          postalCode: "00000",
   133→          department: "Département",
   134→          region: "Région",
   135→          publishedAt: new Date(),
   136→        },
   137→      });
   138→    }
   139→  }
   140→
   141→  // Check if already in favorites
   142→  const existingFavorite = await prisma.favorite.findUnique({
   143→    where: {
   144→      userId_propertyId: {
   145→        userId: session.user.id,
   146→        propertyId: property.id,
   147→      },
   148→    },
   149→  });
   150→
   151→  if (existingFavorite) {
   152→    throw new Error("Ce bien est déjà dans vos favoris");
   153→  }
   154→
   155→  const favorite = await prisma.favorite.create({
   156→    data: {
   157→      userId: session.user.id,
   158→      propertyId: property.id,
   159→      notes: request.notes,
   160→      priority: request.priority ?? "medium",
   161→    },
   162→    include: {
   163→      property: true,
   164→    },
   165→  });
   166→
   167→  logger.debug(
   168→    `✅ [Favorites] Added property ${property.id} to favorites for user ${session.user.id}`,
   169→  );
   170→
   171→  revalidatePath("/favorites");
   172→  revalidatePath("/properties");
   173→  revalidatePath("/orgs", "layout");
   174→
   175→  return favorite;
   176→}
   177→
   178→export async function updateFavoriteAction(request: UpdateFavoriteRequest) {
   179→  const session = await auth.api.getSession({
   180→    headers: await headers(),
   181→  });
   182→
   183→  if (!session?.user.id) {
   184→    redirect("/auth/signin");
   185→  }
   186→
   187→  const favorite = await prisma.favorite.findFirst({
   188→    where: {
   189→      id: request.id,
   190→      userId: session.user.id,
   191→    },
   192→  });
   193→
   194→  if (!favorite) {
   195→    throw new Error("Favori non trouvé");
   196→  }
   197→
   198→  const updatedFavorite = await prisma.favorite.update({
   199→    where: {
   200→      id: request.id,
   201→    },
   202→    data: {
   203→      ...(request.notes !== undefined && { notes: request.notes }),
   204→      ...(request.status && { status: request.status }),
   205→      ...(request.priority && { priority: request.priority }),
   206→    },
   207→    include: {
   208→      property: true,
   209→    },
   210→  });
   211→
   212→  logger.debug(
   213→    `✅ [Favorites] Updated favorite ${request.id} for user ${session.user.id}`,
   214→  );
   215→
   216→  revalidatePath("/favorites");
   217→
   218→  return updatedFavorite;
   219→}
   220→
   221→export async function deleteFavoriteAction(id: string) {
   222→  const session = await auth.api.getSession({
   223→    headers: await headers(),
   224→  });
   225→
   226→  if (!session?.user.id) {
   227→    redirect("/auth/signin");
   228→  }
   229→
   230→  const favorite = await prisma.favorite.findFirst({
   231→    where: {
   232→      id,
   233→      userId: session.user.id,
   234→    },
   235→  });
   236→
   237→  if (!favorite) {
   238→    throw new Error("Favori non trouvé");
   239→  }
   240→
   241→  await prisma.favorite.delete({
   242→    where: {
   243→      id,
   244→    },
   245→  });
   246→
   247→  logger.debug(
   248→    `✅ [Favorites] Deleted favorite ${id} for user ${session.user.id}`,
   249→  );
   250→
   251→  revalidatePath("/favorites");
   252→  revalidatePath("/properties");
   253→  revalidatePath("/orgs", "layout");
   254→}
   255→
   256→export async function toggleFavoriteAction(
   257→  propertyExternalId: string,
   258→): Promise<{ isFavorite: boolean }> {
   259→  logger.debug(
   260→    "🔍 [Favorites] Toggle favorite for property:",
   261→    propertyExternalId,
   262→  );
   263→
   264→  const session = await auth.api.getSession({
   265→    headers: await headers(),
   266→  });
   267→
   268→  if (!session?.user.id) {
   269→    redirect("/auth/signin");
   270→  }
   271→
   272→  logger.debug("🔍 [Favorites] User ID:", session.user.id);
   273→
   274→  const property = await prisma.property.findUnique({
   275→    where: { externalId: propertyExternalId },
   276→  });
   277→
   278→  logger.debug(
   279→    "🔍 [Favorites] Found existing property:",
   280→    property ? "YES" : "NO",
   281→  );
   282→
   283→  if (!property) {
   284→    // Create favorite for new property
   285→    await createFavoriteAction({ propertyId: propertyExternalId });
   286→    return { isFavorite: true };
   287→  }
   288→
   289→  const existingFavorite = await prisma.favorite.findUnique({
   290→    where: {
   291→      userId_propertyId: {
   292→        userId: session.user.id,
   293→        propertyId: property.id,
   294→      },
   295→    },
   296→  });
   297→
   298→  if (existingFavorite) {
   299→    // Remove from favorites
   300→    await deleteFavoriteAction(existingFavorite.id);
   301→    return { isFavorite: false };
   302→  } else {
   303→    // Add to favorites
   304→    await createFavoriteAction({ propertyId: propertyExternalId });
   305→    return { isFavorite: true };
   306→  }
   307→}
   308→

