   166→
   167→export function filtersToSearchCriteria(
   168→  filters: PropertySearchFilters,
   169→): SearchCriteria {
   170→  const criteria: SearchCriteria = {
   171→    page: filters.page,
   172→    limit: 20,
   173→    sortOrder: filters.sortOrder,
   174→  };
   175→
   176→  // Types de transaction (sélection multiple prioritaire)
   177→  if (filters.selectedTypes.length > 0) {
   178→    // Utiliser les nouveaux types multiples
   179→    if (filters.selectedTypes.length === 1) {
   180→      criteria.type = filters.selectedTypes[0];
   181→    }
   182→    // Note: L'API MoteurImmo ne supporte qu'un seul type à la fois
   183→    // Pour supporter multiple types, il faudrait faire plusieurs requêtes
   184→  } else if (filters.type && filters.type !== "all") {
   185→    // Fallback sur l'ancien système
   186→    criteria.type = filters.type as "sale" | "rental";
   187→  }
   188→
   189→  // Catégories de bien (sélection multiple prioritaire)
   190→  if (filters.selectedCategories.length > 0) {
   191→    // Convertir nos catégories UI vers les catégories MoteurImmo
   192→    const moteurImmoCategory = filters.selectedCategories[0]; // Prendre la première pour l'instant
   193→    switch (moteurImmoCategory) {
   194→      case "apartment":
   195→        criteria.category = "flat";
   196→        break;
   197→      case "house":
   198→        criteria.category = "house";
   199→        break;
   200→      case "land":
   201→        criteria.category = "land";
   202→        break;
   203→      case "parking":
   204→        criteria.category = "parking/garage/box";
   205→        break;
   206→      case "commercial":
   207→        criteria.category = "office";
   208→        break;
   209→      case "office":
   210→        criteria.category = "office";
   211→        break;
   212→      case "shop":
   213→        criteria.category = "shop";
   214→        break;
   215→      case "warehouse":
   216→        criteria.category = "warehouse";
   217→        break;
   218→      case "building":
   219→        criteria.category = "building";
   220→        break;
   221→      default:
   222→        criteria.category = moteurImmoCategory as
   223→          | "house"
   224→          | "flat"
   225→          | "land"
   226→          | "parking/garage/box"
   227→          | "office";
   228→    }
   229→    // Note: L'API MoteurImmo supporte les catégories multiples mais notre interface SearchCriteria ne le supporte pas encore
   230→  } else if (filters.category && filters.category !== "all") {
   231→    // Fallback sur l'ancien système
   232→    if (filters.category === "apartment") {
   233→      criteria.category = "flat";
   234→    } else if (filters.category === "house") {
   235→      criteria.category = "house";
   236→    } else if (filters.category === "land") {
   237→      criteria.category = "land";
   238→    } else if (filters.category === "parking") {
   239→      criteria.category = "parking/garage/box";
   240→    } else {
   241→      criteria.category = "office"; // for commercial
   242→    }
   243→  }
   244→
   245→  // Tri
   246→  if (filters.sortBy) {
   247→    if (filters.sortBy === "date") {
   248→      criteria.sortBy = "creationDate";
   249→    } else if (filters.sortBy === "pricePerSquareMeter") {
   250→      criteria.sortBy = "pricePerSquareMeter";
   251→    } else if (filters.sortBy === "lastPriceChange") {
   252→      criteria.sortBy = "lastPriceChangeDate";
   253→    } else {
   254→      criteria.sortBy = filters.sortBy as "price" | "surface";
   255→    }
   256→  }
   257→
   258→  // Localisation - priorité aux villes sélectionnées
   259→  if (filters.selectedCities.length > 0) {
   260→    criteria.city = filters.selectedCities.map((city) => city.name).join(",");
   261→    criteria.postalCode = filters.selectedCities
   262→      .map((city) => city.postalCode)
   263→      .join(",");
   264→  } else if (filters.search || filters.city) {
   265→    const locationQuery = filters.search || filters.city;
   266→    criteria.search = locationQuery;
   267→    if (!filters.search && filters.city) {
   268→      criteria.city = filters.city;
   269→    }
   270→  }
   271→
   272→  // Rayon de recherche
   273→  if (filters.radius) {
   274→    criteria.radius = parseInt(filters.radius);
   275→  }
   276→
   277→  // Prix
   278→  if (filters.priceMin) {
   279→    criteria.priceMin = parseInt(filters.priceMin);
   280→  }
   281→  if (filters.priceMax) {
   282→    criteria.priceMax = parseInt(filters.priceMax);
   283→  }
   284→
   285→  // Surface habitable
   286→  if (filters.surfaceMin) {
   287→    criteria.surfaceMin = parseInt(filters.surfaceMin);
   288→  }
   289→  if (filters.surfaceMax) {
   290→    criteria.surfaceMax = parseInt(filters.surfaceMax);
   291→  }
   292→
   293→  // Surface terrain
   294→  if (filters.landSurfaceMin) {
   295→    criteria.landSurfaceMin = parseInt(filters.landSurfaceMin);
   296→  }
   297→  if (filters.landSurfaceMax) {
   298→    criteria.landSurfaceMax = parseInt(filters.landSurfaceMax);
   299→  }
   300→
   301→  // Pièces et chambres
   302→  if (filters.rooms && filters.rooms !== "all") {
   303→    criteria.roomsMin = parseInt(filters.rooms);
   304→  }
   305→  if (filters.bedrooms && filters.bedrooms !== "all") {
   306→    criteria.bedrooms = parseInt(filters.bedrooms);
   307→  }
   308→
   309→  // Performance énergétique
   310→  if (filters.energyGradeMin) {
   311→    criteria.energyGradeMin = filters.energyGradeMin;
   312→  }
   313→  if (filters.energyGradeMax) {
   314→    criteria.energyGradeMax = filters.energyGradeMax;
   315→  }
   316→
   317→  // Construction
   318→  if (filters.constructionYearMin) {
   319→    criteria.constructionYearMin = parseInt(filters.constructionYearMin);
   320→  }
   321→  if (filters.constructionYearMax) {
   322→    criteria.constructionYearMax = parseInt(filters.constructionYearMax);
   323→  }
   324→  if (filters.floor) {
   325→    criteria.floor = parseInt(filters.floor);
   326→  }
   327→
   328→  // Types d'annonceur (sélection multiple prioritaire)
   329→  if (filters.selectedPublisherTypes.length > 0) {
   330→    criteria.publisherTypes = filters.selectedPublisherTypes;
   331→  } else if (filters.publisherType && filters.publisherType !== "all") {
   332→    // Fallback sur l'ancien système
   333→    criteria.publisherTypes = [filters.publisherType];
   334→  }
   335→
   336→  // Options/Équipements (sélection multiple prioritaire)
   337→  if (filters.selectedEquipment.length > 0) {
   338→    criteria.options = filters.selectedEquipment;
   339→  } else {
   340→    // Fallback sur l'ancien système
   341→    const options: (
   342→      | "hasGarden"
   343→      | "hasParking"
   344→      | "hasLift"
   345→      | "hasTerrace"
   346→      | "hasBalcony"
   347→      | "isNew"
   348→      | "isOld"
   349→      | "hasPriceChanged"
   350→    )[] = [];
   351→    if (filters.hasGarden) options.push("hasGarden");
   352→    if (filters.hasParking) options.push("hasParking");
   353→    if (filters.hasLift) options.push("hasLift");
   354→    if (filters.hasTerrace) options.push("hasTerrace");
   355→    if (filters.hasBalcony) options.push("hasBalcony");
   356→    if (filters.isNew) options.push("isNew");
   357→    if (filters.isOld) options.push("isOld");
   358→    if (filters.hasPriceChanged) options.push("hasPriceChanged");
   359→
   360→    if (options.length > 0) {
   361→      criteria.options = options;
   362→    }
   363→  }
   364→
   365→  // Mots-clés
   366→  if (filters.keywords.trim()) {
   367→    criteria.keywords = filters.keywords
   368→      .split(",")
   369→      .map((k) => k.trim())
   370→      .filter((k) => k);
   371→    criteria.keywordsOperator = filters.keywordsOperator;
   372→  }
   373→
   374→  return criteria;
   375→}
